MagickBooleanType SetQuantumDepth(const Image *image, QuantumInfo *quantum_info, const size_t depth) {
  assert(image != (const Image *) NULL);
  assert(image->signature == MagickSignature);
  assert(quantum_info != (QuantumInfo *) NULL);
  assert(quantum_info->signature == QuantumInfoSignature);

#if defined(MAGICKCORE_DEBUG)
  (void) LogMagickEvent(CoderEvent, GetMagickModule(), "  in SetQuantumDepth: %s", image->filename);
#endif

  quantum_info->depth = depth;

  if (quantum_info->format == UndefinedQuantumFormat)
    return(MagickTrue);

  switch (quantum_info->format) {
    case CharQuantum:
    case ShortQuantum:
    case IntegerQuantum:
    case LongQuantum:
    case SizeQuantum:
    case HugeQuantum:
    case FloatQuantum:
    case DoubleQuantum:
    case UndefinedQuantum:
      break;
  }

  return(MagickTrue);
}

